const B_TXT = `FALL BACK<div style="font-size:30px;letter-spacing:0.06em;color:#d8cfb8;margin-top:6px">TO A STRONGER LINE NEARER THE SUPPLY BASE</div>`;
const DEC = E.decide({ sub: "NIGHT · 2 JULY 1863", a: A_TXT, b: B_TXT, real: 0, t: T_DO - 0.1, tCount: T_TELL, tReveal: T_EVERY, until: T_STAY + 0.2 });
