for (let k = 0; k < 17; k++) { const f = k / 16, la = 39.8268 - f * 0.0170, lo = la > 39.8185 ? -77.2445 - (39.8268 - la) * 0.30 : -77.2470 - (39.8185 - la) * 0.42; GUNS_SEM.push(L(la, lo + 0.0010)); }
